BEGIN;
CREATE TABLE corpus(id INTEGER PRIMARY KEY,url TEXT,title TEXT NOT NULL,author TEXT,datepub TEXT,text TEXT NOT NULL,textoriginal TEXT,citations INTEGER DEFAULT 0,created_at TEXT,updated_at TEXT);
CREATE INDEX idx_author ON corpus(author);CREATE INDEX idx_citations ON corpus(citations);CREATE INDEX idx_datepub ON corpus(datepub);CREATE INDEX idx_title ON corpus(title);
COMMIT;
